/*
 * prog21_date_validator – reproduced from the analysed binary
 *
 * The original binary expects a single command‑line argument that
 * represents a date in the form YYYY‑MM‑DD (exactly 10 characters).
 * It prints “VALID” when the string is a syntactically correct date
 * and the day is valid for the given month (including leap‑year
 * handling).  Any deviation – missing argument, wrong length,
 * wrong separators, non‑digit characters, out‑of‑range month or day –
 * results in the output “INVALID”.
 *
 * The implementation below follows the same observable behaviour
 * without reproducing the obfuscated state‑machine used in the
 * compiled binary.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int is_leap_year(int y)
{
    /* Gregorian leap‑year rule */
    return (y % 4 == 0) && (y % 100 != 0 || y % 400 == 0);
}

int main(int argc, char **argv)
{
    const char *s;
    size_t len;
    int year, month, day;
    static const int days_in_month[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };

    /* No argument → INVALID */
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    s = argv[1];
    len = strlen(s);

    /* Must be exactly “YYYY‑MM‑DD” (10 characters) */
    if (len != 10) {
        puts("INVALID");
        return 0;
    }

    /* Check the two separator characters */
    if (s[4] != '-' || s[7] != '-') {
        puts("INVALID");
        return 0;
    }

    /* All other positions must be decimal digits */
    if (!isdigit((unsigned char)s[0]) || !isdigit((unsigned char)s[1]) ||
        !isdigit((unsigned char)s[2]) || !isdigit((unsigned char)s[3]) ||
        !isdigit((unsigned char)s[5]) || !isdigit((unsigned char)s[6]) ||
        !isdigit((unsigned char)s[8]) || !isdigit((unsigned char)s[9])) {
        puts("INVALID");
        return 0;
    }

    /* Convert the numeric fields */
    year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
            (s[2] - '0') * 10   + (s[3] - '0');

    month = (s[5] - '0') * 10 + (s[6] - '0');
    day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* Month must be 1‑12 */
    if (month < 1 || month > 12) {
        puts("INVALID");
        return 0;
    }

    /* Determine the maximum valid day for the month */
    int max_day = days_in_month[month - 1];
    if (month == 2 && is_leap_year(year))
        max_day = 29;

    /* Day must be within the allowed range */
    if (day < 1 || day > max_day) {
        puts("INVALID");
        return 0;
    }

    /* All checks passed */
    puts("VALID");
    return 0;
}
